const items = $input.all();
const results = [];
const now = new Date();
const dateFolder = `${now.getFullYear()}/${String(now.getMonth() + 1).padStart(2, '0')}/${String(now.getDate()).padStart(2, '0')}`;

for (const item of items) {
  const from = item.json.from || 'unknown';
  const subject = item.json.subject || 'no-subject';
  const attachmentCount = item.json.attachments ? item.json.attachments.length : 0;

  // Get binary data keys for attachments
  const binaryKeys = item.binary ? Object.keys(item.binary) : [];

  for (const key of binaryKeys) {
    const binaryData = item.binary[key];
    results.push({
      json: {
        fileName: binaryData.fileName || `attachment_${key}`,
        mimeType: binaryData.mimeType || 'application/octet-stream',
        dateFolder: dateFolder,
        emailFrom: from,
        emailSubject: subject,
        savedAt: now.toISOString()
      },
      binary: {
        data: binaryData
      }
    });
  }
}
return results;

